class Solution {
  public int maxValueAfterReverse(int[] nums) {
    int base = 0, gain = 0;
    for (int i = 0; i + 1 < nums.length; i++) {
      int a = nums[i], b = nums[i + 1];
      base += Math.abs(a - b);
      gain = Math.max(gain, Math.abs(nums[0] - b) - Math.abs(a - b));
      gain = Math.max(gain, Math.abs(nums[nums.length - 1] - a) - Math.abs(a - b));
    }
    int innerLow = Integer.MAX_VALUE, innerHigh = Integer.MIN_VALUE;
    for (int i = 0; i + 1 < nums.length; i++) {
      int lo = Math.min(nums[i], nums[i + 1]), hi = Math.max(nums[i], nums[i + 1]);
      innerLow = Math.min(innerLow, hi);
      innerHigh = Math.max(innerHigh, lo);
    }
    if (innerLow != Integer.MAX_VALUE) gain = Math.max(gain, 2 * (innerHigh - innerLow));
    return base + gain;
  }
}
